#!/bin/bash
# Print the three most frequent IP addresses in access.log,
# most frequent first; break ties by first appearance in the log.
awk '
{
    ip = $1
    count[ip]++
    if (!(ip in first_seen)) {
        first_seen[ip] = NR
        order[++n] = ip
    }
}
END {
    for (i = 1; i <= n; i++) {
        ip = order[i]
        print count[ip] "\t" ip
    }
}
' access.log | sort -k1,1nr -k2,2 | sort -s -t$'\t' -k2,2 -k1,1nr | awk -F'\t' 'NR <= 3 { print $2 }'

#!/bin/bash
# Print the three most frequent IP addresses in access.log,
# most frequent first; break ties by first appearance in the log.
awk '
{
    ip = $1
    count[ip]++
    if (!(ip in first_seen)) {
        first_seen[ip] = NR
        order[++n] = ip
    }
}
END {
    for (i = 1; i <= n; i++) {
        ip = order[i]
        print count[ip] "\t" first_seen[ip] "\t" ip
    }
}
' access.log | sort -t"$(printf '\t')" -k1,1nr -k2,2n | awk -F"\t" 'NR <= 3 { print $3 }'
